CREATE TABLE terms (
  term_id    INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  start_date TEXT NOT NULL
);
INSERT INTO terms (name, start_date) VALUES ('Fall 2024', '2024-08-24');
SELECT * FROM terms;

CREATE TABLE rooms (
  room_id     INTEGER PRIMARY KEY,
  building    TEXT NOT NULL,
  room_number TEXT NOT NULL,
  capacity    INTEGER NOT NULL CHECK (capacity > 0),
  room_type   TEXT NOT NULL DEFAULT 'lecture' CHECK (room_type IN ('lecture','lab','seminar')),
  UNIQUE (building, room_number)
);
INSERT INTO rooms (building, room_number, capacity) VALUES ('Ritter', '101', 40);
SELECT * FROM rooms;

CREATE TABLE departments (department_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE employees (
  employee_id   INTEGER PRIMARY KEY,
  name          TEXT NOT NULL,
  department_id INTEGER REFERENCES departments(department_id)
);
INSERT INTO departments VALUES (1, 'Biology');
INSERT INTO employees VALUES (1, 'Ava', 1);
SELECT e.name, d.name AS department FROM employees e JOIN departments d USING (department_id);

CREATE TABLE courses (course_id INTEGER PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE sections (
  section_id INTEGER PRIMARY KEY,
  course_id  INTEGER NOT NULL REFERENCES courses(course_id) ON DELETE CASCADE
);
INSERT INTO courses VALUES (1, 'Databases');
INSERT INTO sections VALUES (10, 1);
DELETE FROM courses WHERE course_id = 1;
SELECT COUNT(*) AS sections_left FROM sections;

CREATE TABLE employees (
  employee_id INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  manager_id  INTEGER REFERENCES employees(employee_id),
  CHECK (manager_id <> employee_id)
);
INSERT INTO employees VALUES (1, 'President', NULL);
INSERT INTO employees VALUES (2, 'Provost', 1);
SELECT e.name, m.name AS manager FROM employees e LEFT JOIN employees m ON m.employee_id = e.manager_id;

CREATE TABLE students (student_id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE clubs (club_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE memberships (
  student_id INTEGER NOT NULL REFERENCES students(student_id),
  club_id    INTEGER NOT NULL REFERENCES clubs(club_id),
  role       TEXT NOT NULL DEFAULT 'member',
  PRIMARY KEY (student_id, club_id)
);
INSERT INTO students VALUES (1, 'Ava'); INSERT INTO clubs VALUES (1, 'Chess');
INSERT INTO memberships (student_id, club_id) VALUES (1, 1);
SELECT * FROM memberships;

CREATE TABLE payments (payment_id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL, amount REAL NOT NULL);
ALTER TABLE payments ADD COLUMN method TEXT NOT NULL DEFAULT 'card';
CREATE INDEX idx_payments_student ON payments(student_id);
PRAGMA index_list(payments);

CREATE TABLE departments (dept_code TEXT PRIMARY KEY, dept_name TEXT NOT NULL);
CREATE TABLE courses (course_code TEXT PRIMARY KEY, course_title TEXT NOT NULL, dept_code TEXT NOT NULL REFERENCES departments(dept_code));
CREATE TABLE students (student_id INTEGER PRIMARY KEY, student_name TEXT NOT NULL);
CREATE TABLE registrations (
  student_id  INTEGER NOT NULL REFERENCES students(student_id),
  course_code TEXT NOT NULL REFERENCES courses(course_code),
  grade       TEXT,
  PRIMARY KEY (student_id, course_code)
);
SELECT name FROM sqlite_master WHERE type = 'table';

CREATE TABLE student_major_history (
  student_id INTEGER NOT NULL,
  major_id   INTEGER NOT NULL,
  valid_from TEXT NOT NULL,
  valid_to   TEXT,
  PRIMARY KEY (student_id, major_id, valid_from),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
INSERT INTO student_major_history VALUES (1, 1, '2022-08-24', '2023-05-12');
INSERT INTO student_major_history VALUES (1, 2, '2023-08-24', NULL);
SELECT * FROM student_major_history WHERE valid_to IS NULL;
